(() => {
  'use strict';
  const root = document.documentElement;
  if (root?.dataset.eperangkatLogoFixInstalled === '1') return;
  if (root) root.dataset.eperangkatLogoFixInstalled = '1';

  const VERSION = '20260909-logo-assets-2';
  const LOGOS = {
    'logo-buol.png': 'data:image/png;base64,',
    'tut-wuri-handayani.png': 'data:image/png;base64,'
  };

  const documentPrototype = Document.prototype;
  if (!documentPrototype.__eperangkatLogoWriteGuard) {
    documentPrototype.__eperangkatLogoWriteGuard = true;
    const nativeWrite = documentPrototype.write;
    const scriptUrl = document.currentScript?.src || `${location.origin}/logo-fix.js?v=${VERSION}`;
    const scriptTag = '<scr' + 'ipt src="' +
      scriptUrl.replace(/&/g, '&amp;').replace(/"/g, '&quot;') +
      '"></scr' + 'ipt>';
    documentPrototype.write = function (...parts) {
      let html = parts.join('');
      if (this === document && /<\/body>/i.test(html) && !html.includes('logo-fix.js')) {
        html = html.replace(/<\/body>/i, scriptTag + '</body>');
      }
      return nativeWrite.call(this, html);
    };
  }

  function replacementFor(value) {
    if (!value || /^(?:data:|blob:)/i.test(value)) return '';
    let pathname = '';
    try {
      pathname = new URL(value, location.href).pathname.toLowerCase();
    } catch (_) {
      pathname = String(value).split(/[?#]/, 1)[0].toLowerCase();
    }
    if (!pathname.includes('/assets/logos/')) return '';
    for (const [fileName, target] of Object.entries(LOGOS)) {
      if (pathname.endsWith(`/${fileName}`)) return target;
    }
    return '';
  }

  function fixImage(image) {
    if (!(image instanceof HTMLImageElement)) return;
    const current = image.getAttribute('src') || '';
    const replacement = replacementFor(current);
    if (replacement && current !== replacement) image.setAttribute('src', replacement);
  }

  function fixTree(root) {
    if (!root) return;
    if (root instanceof HTMLImageElement) fixImage(root);
    if (root.querySelectorAll) root.querySelectorAll('img[src]').forEach(fixImage);
  }

  fixTree(document);
  const observer = new MutationObserver(records => {
    for (const record of records) {
      if (record.type === 'attributes') fixImage(record.target);
      for (const node of record.addedNodes) {
        if (node.nodeType === Node.ELEMENT_NODE) fixTree(node);
      }
    }
  });
  observer.observe(document.documentElement, {
    subtree: true,
    childList: true,
    attributes: true,
    attributeFilter: ['src']
  });

  window.addEventListener('DOMContentLoaded', () => fixTree(document));
  window.addEventListener('load', () => fixTree(document));
})();
